    context: Local PageContext := contextFor(session)
    guard: Local GuardResult := adminGuard(session, context)
    if guard.allowed == false {
        return sessionCommit(session, guard.refusal)
    }

    if csrfValid(session, request) == false {
        return sessionCommit(session, Web.text("Geçersiz form belirteci.", 403))
    }

    id: Local Int := validationPositiveInt(request.form("question_id"))
    title: Local String := validationField(request.form("title"))
    topic: Local String := validationField(request.form("topic"))
    body: Local String := validationField(request.form("body"))

    errors: Local List<String> := []
    if title == "" {
        errors.add("Başlık gerekli.")
    }

    if topic == "" {
        errors.add("Konu gerekli.")
    }

    if body == "" {
        errors.add("Soru metni gerekli.")
    }

    if len(errors) > 0 {
        return sessionCommit(
            session
            adminQuestionForm(
                session
                context
                id
                title
                topic
                body
                errors
                ""
            )
        )
    }

    author: Local UserRecord? := context.user
    authorId: Local Int := 0
