        authorId = author.id
    }

    if id == 0 {
        questionsCreate(title, topic, body, authorId)
        flashSet(session, "success", "Soru taslak olarak kaydedildi.")
    }
    else {
        questionsUpdate(id, title, topic, body)
        flashSet(session, "success", "Soru güncellendi.")
    }

    return sessionCommit(session, Web.redirect("/admin/questions"))
